<?php require __DIR__.'/config.php'; if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $email=strtolower(trim($_POST['email'])); $secret=client_secret($_POST['password']); $totp=base64_encode(random_bytes(10)); try { $stmt=$db->prepare('INSERT INTO users(email,password_hash,password_changed_at,totp_secret) VALUES(?,?,?,?)'); $stmt->execute([$email,password_hash($secret,PASSWORD_DEFAULT),gmdate('c'),$totp]); flash('Konto erstellt. TOTP-Schluessel fuer die Demo: '.$totp); header('Location: index.php'); exit; } catch (PDOException $e) { flash('Diese E-Mail ist bereits registriert.'); } } page('<h1>Konto anlegen</h1>'.show_flash().'<form method="post" onsubmit="return protect(this)"><input type="hidden" name="csrf" value="'.h(csrf()).'"><label>E-Mail<input type="email" name="email" required></label><label>Passwort<input type="password" name="password" minlength="8" required></label><button>Registrieren</button></form><p><a href="index.php">Zur Anmeldung</a></p><script>async function protect(f){let b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(f.password.value));f.password.value=Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,"0")).join("");return true}</script>'); ?>